 for(int y=0;y<8;++y)for(int x=0;x<8;++x){pixels.pixels[std::size_t(y)*8+x]=0xff000000U|(std::uint32_t(x*25)<<16)|(std::uint32_t(y*25)<<8)|0x33U;mask.pixels[std::size_t(y)*8+x]=(std::uint32_t((x+1)*28)<<24)|0x00ffffffU;}
 d.assets.emplace_back(RasterAsset{"paint",std::move(pixels)});d.assets.emplace_back(RasterAsset{"mask",std::move(mask)});
 VectorPath path;path.commands={MoveTo{{0,0}},LineTo{{8,0}},LineTo{{8,8}},LineTo{{0,8}},ClosePath{}};path.fill=SolidPaint{0xff123456U};d.assets.emplace_back(VectorAsset{"vector",{8,8},{path}});
