 MotionKeyframe a;a.frame=0;a.value.opacity=1;MotionKeyframe b;b.frame=1;b.value.position={0,1};b.value.opacity=.5;top.motion={a,b};d.layers.emplace_back(StaticBitmapLayer{top,StaticSource{"paint"}});return d;
