RasterLayer layerPixels(Document doc,int frame,std::size_t index){layerProperties(doc.layers[index]).visible=true;auto r=renderFrameLayerTiles(doc,frame,index,{{{{0,0},doc.extent},doc.extent}});check(r.ok()&&r.visible&&r.tiles.size()==1,"layer render failed");return r.tiles[0].pixels;}
RasterLayer expected(const RasterLayer& source,const iiGraphicAdjust::MeshQuad& quad,CanvasExtent extent){auto in=iiGraphicAdjust::fromArgb32(source.width,source.height,source.pixels);check(bool(in),"convert failed");auto out=iiGraphicAdjust::perspectiveCrop(in->view(),quad,extent.width,extent.height);check(bool(out),"crop oracle failed");auto pixels=iiGraphicAdjust::toArgb32(out->view());check(bool(pixels),"convert output failed");return {extent.width,extent.height,std::move(*pixels)};}
void send(CanvasView& view,ii::gui::WidgetInputKind kind,double x,double y){ii::gui::WidgetInput e;e.kind=kind;e.x=x;e.y=y;e.buttons=1;check(view.input(e).has_value(),"perspective input failed");}
